#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 * - Keep original Gauss–Seidel update order and iteration space.
 * - Introduce a restrict-qualified alias for A to improve alias analysis.
 * - Use a 1D sliding window along j to reuse three neighbors from the
 *   previous column, reducing memory loads from 9 to 6 per point.
 * - Precompute the reciprocal of 9 once outside the loops.
 */
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Effective iteration bounds as defined by PolyBench macros. */
  const int tsteps_pb = _PB_TSTEPS;
  const int n_pb      = _PB_N;

  /* Alias the 2D array through a restrict-qualified pointer.  All accesses
     within this kernel go through 'a', which allows the compiler to assume
     no external aliasing for the matrix data. */
  DATA_TYPE (*restrict a)[n] = A;

  /* Precompute 1/9 in the appropriate scalar type. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

  int t, i, j;

#pragma scop
  for (t = 0; t <= tsteps_pb - 1; ++t)
  {
    for (i = 1; i <= n_pb - 2; ++i)
    {
      /* Pointers to the three rows involved in the 3x3 stencil. */
      DATA_TYPE *row_im1 = a[i - 1];
      DATA_TYPE *row_i   = a[i];
      DATA_TYPE *row_ip1 = a[i + 1];

      /* For j == 1, the left neighbors are at column 0. These three values
         are carried across iterations of the inner j-loop, forming a sliding
         window horizontally. */
      DATA_TYPE prev_im1 = row_im1[0]; /* A[i-1][j-1] at j = 1 */
      DATA_TYPE prev_i   = row_i[0];   /* A[i][j-1]   at j = 1 */
      DATA_TYPE prev_ip1 = row_ip1[0]; /* A[i+1][j-1] at j = 1 */

      for (j = 1; j <= n_pb - 2; ++j)
      {
        /* Load the remaining six neighbors needed for the 3x3 stencil.
           All loads are done before updating row_i[j] so that:
             - A[i][j+1] is the old (east) neighbor,
             - A[i+1][*] are still the old (south) neighbors,
           exactly matching the original Gauss–Seidel update semantics. */
        DATA_TYPE cur_im1  = row_im1[j];     /* A[i-1][j]   */
        DATA_TYPE next_im1 = row_im1[j + 1]; /* A[i-1][j+1] */

        DATA_TYPE cur_i    = row_i[j];       /* A[i][j]     */
        DATA_TYPE next_i   = row_i[j + 1];   /* A[i][j+1]   */

        DATA_TYPE cur_ip1  = row_ip1[j];     /* A[i+1][j]   */
        DATA_TYPE next_ip1 = row_ip1[j + 1]; /* A[i+1][j+1] */

        /* Accumulate the 9-point stencil using a sliding window:
             UL  = prev_im1
             UM  = cur_im1
             UR  = next_im1
             ML  = prev_i        (updated west neighbor)
             MM  = cur_i
             MR  = next_i
             LL  = prev_ip1
             LM  = cur_ip1
             LR  = next_ip1
        */
        DATA_TYPE sum =
            prev_im1  + cur_im1  + next_im1 +
            prev_i    + cur_i    + next_i   +
            prev_ip1  + cur_ip1  + next_ip1;

        DATA_TYPE new_val = sum * inv9;
        row_i[j] = new_val;

        /* Slide the window one column to the right:
           - Current column becomes left neighbor for the next iteration.
           - The just-computed center becomes the new west neighbor
             A[i][j-1] for the subsequent point, as in the original
             Gauss–Seidel scheme. */
        prev_im1 = cur_im1;
        prev_i   = new_val;
        prev_ip1 = cur_ip1;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
