      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   ------------------
   - Preserves the original Gauss–Seidel update order:
       for each time step t:
         for i = 1..n-2
           for j = 1..n-2
       The (i,j) points are still visited in strict lexicographic order.
   - Uses sliding 3-point horizontal windows on the three rows involved in
     the 3x3 stencil (row i-1, i, i+1). This reduces the number of loads
     per grid point from 9 to ~3 while keeping the exact same neighbor
     values as the original code.
   - Reuses the freshly computed A[i][j] as the left neighbor for A[i][j+1]
     to correctly implement in-place Gauss–Seidel semantics.
*/
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Hoist the reciprocal of 9 out of the loops. This replaces a division
     by a multiplication, which is significantly cheaper on modern CPUs. */
  const DATA_TYPE c_one_ninth = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (t = 0; t < tsteps; ++t)
  {
    /* Update interior points only; the boundary (0 and n-1 in each
       dimension) remains unchanged across all time steps. */
    for (i = 1; i < n - 1; ++i)
    {
      /* Row pointers improve locality and give the compiler simpler
         addressing expressions for the inner loop.  Each pointer is
         'restrict' because different rows of a 2D array do not alias. */
      DATA_TYPE *restrict row_im1 = &A[i-1][0]; /* row i-1 (top)    */
      DATA_TYPE *restrict row_i   = &A[i  ][0]; /* row i   (center) */
      DATA_TYPE *restrict row_ip1 = &A[i+1][0]; /* row i+1 (bottom) */

      /* Number of the last interior column (j = 1..maxj). */
      const int maxj = n - 2;

      /* Initialize 3-point horizontal windows for the three rows.
         At column j we need values at j-1, j, j+1.
         For j == 1 that window is columns {0,1,2}. */

      /* Top row window: columns {0,1,2} for j == 1. */
      DATA_TYPE top_left   = row_im1[0];
      DATA_TYPE top_mid    = row_im1[1];
      DATA_TYPE top_right  = row_im1[2];
      DATA_TYPE sum_top    = top_left + top_mid + top_right;

      /* Bottom row window: columns {0,1,2} for j == 1. */
      DATA_TYPE bot_left   = row_ip1[0];
      DATA_TYPE bot_mid    = row_ip1[1];
      DATA_TYPE bot_right  = row_ip1[2];
      DATA_TYPE sum_bot    = bot_left + bot_mid + bot_right;

      /* Middle row values:
         - mid_left  : left neighbor, which will be the UPDATED value
                       from column j-1 for j > 1 (or the boundary at j=0
                       when j == 1).
         - mid_mid   : center (old) value at column j.
         - mid_right : right (old) neighbor at column j+1. */
      DATA_TYPE mid_left   = row_i[0];
      DATA_TYPE mid_mid    = row_i[1];
      DATA_TYPE mid_right  = row_i[2];

      for (j = 1; j < n - 1; ++j)
      {
        /* Horizontal 3-point sum on the current (middle) row:
           For j == 1: uses row_i[0], row_i[1], row_i[2] (all old).
           For j > 1 : uses
             - new A[i][j-1]   (mid_left),
             - old A[i][j]     (mid_mid),
             - old A[i][j+1]   (mid_right),
           exactly matching the Gauss–Seidel in-place semantics. */
        DATA_TYPE sum_mid = mid_left + mid_mid + mid_right;

        /* Combine vertical contributions from the three rows. */
        DATA_TYPE sum_all = sum_top + sum_mid + sum_bot;

        /* In-place Gauss–Seidel update. */
        DATA_TYPE new_center = sum_all * c_one_ninth;
        row_i[j] = new_center;

        /* Slide all three 3-point windows one column to the right,
           except after the last interior column (j == maxj).
           This preserves the strict lexicographic (i,j) processing
           order and the exact neighbor usage of the original code. */
        if (j < maxj)
        {
          const int jp2 = j + 2; /* index of new rightmost point */

          /* Top row window:
             Before: sum_top == row_im1[j-1] + row_im1[j] + row_im1[j+1]
             After : we want window {j, j+1, j+2}. */
          DATA_TYPE top_new_right = row_im1[jp2];
          sum_top += top_new_right - top_left;
          top_left  = top_mid;
          top_mid   = top_right;
          top_right = top_new_right;

          /* Bottom row window: same logic as for the top row. */
          DATA_TYPE bot_new_right = row_ip1[jp2];
          sum_bot += bot_new_right - bot_left;
          bot_left  = bot_mid;
          bot_mid   = bot_right;
          bot_right = bot_new_right;

          /* Middle row window:
             - The new left neighbor for the next j is the value we
               just computed (Gauss–Seidel in-place dependency).
             - The new center is the previous right neighbor, which
               still holds the *old* A[i][j+1].
             - The new right neighbor is A[i][j+2], which is still old
               because we have not reached column j+2 yet. */
          mid_left  = new_center;
          mid_mid   = mid_right;
          mid_right = row_i[jp2];
        }
      } /* end of j loop */
    }   /* end of i loop */
  }     /* end of t loop */
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
