/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 * - Use a row-pointer view (Aview) to reduce address arithmetic.
 * - Use restrict-qualified row pointers (row_above, row, row_below) so the
 *   compiler knows rows do not alias and can keep more values in registers.
 * - Hoist the constant denominator out of the inner loops.
 * - Keep the exact iteration order (t, i, j) to preserve Gauss–Seidel
 *   semantics; no tiling, loop interchange, or parallelization is applied,
 *   because those would change which neighbors are "new" vs "old".
 */
static
void kernel_seidel_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  (void)tsteps; /* tsteps and n are used through PolyBench macros. */
  (void)n;

  /* Row-major view of A with an explicit VLA pointer.
   * Using this indirection lets us attach __restrict and improves
   * code generation for row accesses.
   */
  DATA_TYPE (* __restrict Aview)[n] = A;

  /* Hoist the divisor as a constant; the compiler is free to turn
   * division by a constant into multiplication by a precomputed
   * reciprocal while respecting IEEE semantics.
   */
  const DATA_TYPE denom = SCALAR_VAL(9.0);

  int t, i, j;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
  {
    /* i-loop: must remain outermost over j to preserve Gauss–Seidel
     * update order (each row depends on the fully updated previous row).
     */
    for (i = 1; i <= _PB_N - 2; i++)
    {
      /* Row pointers for better locality and fewer repeated address
       * calculations. Each row is contiguous and distinct, so marking
       * them restrict is valid and helps the optimizer.
       */
      DATA_TYPE * __restrict row_above = Aview[i-1];
      DATA_TYPE * __restrict row       = Aview[i];
      DATA_TYPE * __restrict row_below = Aview[i+1];

      /* j-loop: must scan left to right; each point depends on the
       * updated value of row[j-1] (left neighbor). We do not apply any
       * transformations that would change this order.
       */
      for (j = 1; j <= _PB_N - 2; j++)
      {
        /* Explicitly load the stencil neighborhood into temporaries.
         * This makes the dataflow clear to the compiler and reduces
         * redundant loads / address arithmetic.
         */
        const DATA_TYPE a00 = row_above[j-1];
        const DATA_TYPE a01 = row_above[j];
        const DATA_TYPE a02 = row_above[j+1];

        const DATA_TYPE a10 = row[j-1];
        const DATA_TYPE a11 = row[j];
        const DATA_TYPE a12 = row[j+1];

        const DATA_TYPE a20 = row_below[j-1];
        const DATA_TYPE a21 = row_below[j];
        const DATA_TYPE a22 = row_below[j+1];

        const DATA_TYPE sum =
            a00 + a01 + a02 +
            a10 + a11 + a12 +
            a20 + a21 + a22;

        row[j] = sum / denom;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
