}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   -------------------
   - Keeps the same Gauss–Seidel update order: (t, i, j) in lexicographic order.
   - Uses row pointers to avoid repeated 2D index arithmetic.
   - For each row, uses a sliding 3x3 stencil window along j:
       * Reduces the number of loads from ~9 per grid point to ~3 per point
         after the first column, by reusing already loaded neighbor values.
       * Carefully distinguishes "old" vs "new" values to preserve the exact
         Gauss–Seidel dependency pattern:
           - A[i][j-1] is read as "new" starting from j >= 2.
           - A[i][j], A[i][j+1] and row i+1 neighbors remain "old" within
             the current time step.
   - Handles small sizes (n == 3, n == 4) in simple scalar code paths to
     avoid out-of-bounds accesses while still using the optimized strategy
     for the common case (n >= 5).
*/
static
void kernel_seidel_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i;

  /* PolyBench provides possibly sanitized loop bounds via these macros. */
  const int _tsteps = _PB_TSTEPS;
  const int _n      = _PB_N;

  /* Parameters are kept for interface compatibility; loop bounds
     are taken from PolyBench macros as in the original code. */
  (void)tsteps;
  (void)n;

#pragma scop
  for (t = 0; t <= _tsteps - 1; ++t)
  {
    /* For _n <= 2 there is no interior point; the inner loop
       will be skipped automatically. */
    for (i = 1; i <= _n - 2; ++i)
    {
      /* Row pointers for faster addressing; rows do not overlap so
         we can safely use 'restrict' for better alias analysis. */
      DATA_TYPE * restrict const Ai_minus1 = A[i-1];
      DATA_TYPE * restrict const Ai        = A[i];
      DATA_TYPE * restrict const Ai_plus1  = A[i+1];

      if (_n == 3)
      {
        /* Special case: only one interior column j = 1.
           Directly compute the 3x3 average. */
        const DATA_TYPE sum =
          Ai_minus1[0] + Ai_minus1[1] + Ai_minus1[2] +
          Ai      [0] + Ai      [1] + Ai      [2] +
          Ai_plus1[0] + Ai_plus1[1] + Ai_plus1[2];

        Ai[1] = sum / SCALAR_VAL(9.0);
      }
      else
      {
        /* Common cases: _n >= 4 */

        /* ----- j = 1 (left-most interior column) -----
           At j = 1, the left neighbor A[i][0] is a boundary point which is
           never updated inside the time step, so it is always "old". */
        const DATA_TYPE top0    = Ai_minus1[0];
        const DATA_TYPE top1    = Ai_minus1[1];
        const DATA_TYPE top2    = Ai_minus1[2];

        const DATA_TYPE bottom0 = Ai_plus1[0];
        const DATA_TYPE bottom1 = Ai_plus1[1];
        const DATA_TYPE bottom2 = Ai_plus1[2];

        const DATA_TYPE center0 = Ai[0];
        const DATA_TYPE center1 = Ai[1];
        const DATA_TYPE center2 = Ai[2];

        DATA_TYPE sum1 = top0 + top1 + top2;
        DATA_TYPE sum2 = center0 + center1 + center2;
        DATA_TYPE sum3 = bottom0 + bottom1 + bottom2;

        DATA_TYPE new_center1 = (sum1 + sum2 + sum3) / SCALAR_VAL(9.0);
        Ai[1] = new_center1;

        if (_n == 4)
        {
          /* Only one more interior column: j = 2.
             We can compute it directly using the freshly updated A[i][1]. */
          const int j = 2;

          sum1 = top1 + top2 + Ai_minus1[j+1];   /* A[i-1][1], A[i-1][2], A[i-1][3] */
          sum2 = new_center1 + center2 + Ai[j+1];/* A[i][1]^new, A[i][2]^old, A[i][3]^old */
          sum3 = bottom1 + bottom2 + Ai_plus1[j+1];

          Ai[j] = (sum1 + sum2 + sum3) / SCALAR_VAL(9.0);
        }
        else
        {
          /* ----- Main optimized path: _n >= 5 -----
             Use a sliding 3x3 window along the row to greatly reduce
             the number of memory loads per point.

             Invariants before computing column 'j' (j >= 2 and j <= _n-3):

               top_left    = A[i-1][j-1]
               top_mid     = A[i-1][j]
               bottom_left = A[i+1][j-1]
               bottom_mid  = A[i+1][j]
               left_new    = A[i][j-1] (new, computed in previous step)
               center_mid_old   = A[i][j]   (old)
               center_right_old = A[i][j+1] (old)
          */

          DATA_TYPE top_left     = top1;     /* A[i-1][1] */
          DATA_TYPE top_mid      = top2;     /* A[i-1][2] */

          DATA_TYPE bottom_left  = bottom1;  /* A[i+1][1] */
          DATA_TYPE bottom_mid   = bottom2;  /* A[i+1][2] */

          DATA_TYPE left_new     = new_center1; /* A[i][1] just updated */
          DATA_TYPE center_mid_old   = center2;  /* A[i][2] old */
          DATA_TYPE center_right_old = Ai[3];    /* A[i][3] old */

          int j;
          for (j = 2; j <= _n - 3; ++j)
          {
            const DATA_TYPE top_right    = Ai_minus1[j+1]; /* A[i-1][j+1] */
            const DATA_TYPE bottom_right = Ai_plus1[j+1];  /* A[i+1][j+1] */

            sum1 = top_left + top_mid + top_right;
            sum2 = left_new + center_mid_old + center_right_old;
            sum3 = bottom_left + bottom_mid + bottom_right;

            const DATA_TYPE new_val =
              (sum1 + sum2 + sum3) / SCALAR_VAL(9.0);

            Ai[j] = new_val;

            /* Slide the window by one column to the right:
               New 'left' neighbors become the previous 'mid' or 'new' values,
               while we bring in a fresh A[i][j+2] (still "old") as the new
               right neighbor for the *next* iteration. */
            top_left     = top_mid;
            top_mid      = top_right;

            bottom_left  = bottom_mid;
            bottom_mid   = bottom_right;

            left_new         = new_val;          /* A[i][j] new */
            center_mid_old   = center_right_old; /* becomes A[i][j+1] old */
            center_right_old = Ai[j+2];          /* A[i][j+2] old */
          }

          /* Last interior point in the row: j = _n - 2.
             The invariants after the loop (with j == _n-3) guarantee that:
               top_left        = A[i-1][_n-3]
               top_mid         = A[i-1][_n-2]
               bottom_left     = A[i+1][_n-3]
               bottom_mid      = A[i+1][_n-2]
               left_new        = A[i][_n-3] new
               center_mid_old  = A[i][_n-2] old
               center_right_old= A[i][_n-1] old
             We just need to load the remaining top and bottom right neighbors. */
          const int j_last = _n - 2;

          const DATA_TYPE top_right_last    = Ai_minus1[j_last+1];   /* A[i-1][_n-1] */
          const DATA_TYPE bottom_right_last = Ai_plus1[j_last+1];    /* A[i+1][_n-1] */

          sum1 = top_left + top_mid + top_right_last;
          sum2 = left_new + center_mid_old + center_right_old;
          sum3 = bottom_left + bottom_mid + bottom_right_last;

          Ai[j_last] = (sum1 + sum2 + sum3) / SCALAR_VAL(9.0);
        }
      }
    }
  }
#pragma endscop

}


